import rhinoscriptsyntax as rs

curve_id = rs.GetObject("选择一条曲线", rs.filter.curve)
point_id = rs.GetObject("选择一个点", rs.filter.point)
if not curve_id or not point_id:
    print("未选择有效对象")
else:
    point = rs.PointCoordinates(point_id)
    # 检查曲线是否为直线
    if rs.IsLine(curve_id):
        line_pts = rs.CurvePoints(curve_id)
        closest = rs.LineClosestPoint(line_pts, point)
    else:
        # 对于非直线，使用曲线最近点函数
        closest = rs.EvaluateCurve(curve_id, rs.CurveClosestPoint(curve_id, point))
    if closest:
        rs.AddPoint(closest)
    else:
        print("无法计算最近点")

