import rhinoscriptsyntax as rs

def safe_set_osnap(mode):
    """
    安全设置对象捕捉模式。
    参数 mode 为整数或 None。
    """
    if mode is None:
        # 不改变当前模式，只返回当前模式
        return rs.OsnapMode()
    try:
        mode = int(mode)
        # 检查是否为有效的捕捉模式（非负整数）
        if mode < 0:
            raise ValueError("Mode must be a non-negative integer.")
        return rs.OsnapMode(mode)
    except (TypeError, ValueError):
        # 如果转换失败或值无效，返回当前模式
        print("Invalid mode, keeping current settings.")
        return rs.OsnapMode()

# 示例用法
