def safe_send_keystrokes(keys=None, add_return=True):
    if keys is None:
        print("No keys provided, skipping.")
        return
    if not isinstance(keys, str):
        try:
            keys = str(keys)
        except:
            print("Cannot convert keys to string.")
            return
    rs.SendKeystrokes(keys, add_return)

