import rhinoscriptsyntax as rs

objects = rs.GetObjects("选择要移动的物件", preselect=True)
if objects:
    rs.StatusBarProgressMeterShow("移动物件", 0, len(objects))
    for i, obj in enumerate(objects):
        point = rs.PointCoordinates(obj)
        if point:
            new_point = (point[0] + 1, point[1], point[2])
            rs.MoveObject(obj, new_point)
        rs.StatusBarProgressMeterUpdate(i+1)
    rs.StatusBarProgressMeterHide()
else:
    print("未选择物件")

