def safe_set_template(filename):
    """安全设置默认模板文件，参数为None或空字符串时返回当前模板路径。"""
    if filename is None or filename == "":
        # 不进行设置，仅返回当前模板
        return rs.TemplateFile()
    else:
        # 设置新模板，返回旧模板路径
        return rs.TemplateFile(filename)

# 示例使用
current = safe_set_template(None)
print("当前模板:", current)

# 设置新模板
new = safe_set_template("C:\\Templates\\Custom.3dm")
print("旧模板:", new)

