import rhinoscriptsyntax as rs

def safe_block_status(block_name):
    if not block_name or not rs.IsBlock(block_name):
        return None
    status = rs.BlockStatus(block_name)
    if status == -3:
        return "不是链接块"
    elif status == -2:
        return "文件无法打开或读取"
    elif status == -1:
        return "文件未找到"
    else:
        return status

# 示例
print(safe_block_status("NonExistentBlock"))  # None
print(safe_block_status("SomeBlock"))

import rhinoscriptsyntax as rs

block_name = rs.GetString("选择要检查的块")
if not block_name:
    print("未输入块名称")
else:
    if rs.IsBlock(block_name):
        status = rs.BlockStatus(block_name)
        if status == -3:
            print("该块不是链接块")
        elif status == 0:
            print("链接块是最新的")
        elif status == 1:
            print("外部文件已更新，需要重新加载")
        elif status == 2:
            print("外部文件比块旧")
        elif status == 3:
            print("外部文件与块不同")
        else:
