            divisions = 4  # 5个点需要4段
            curve_points = []
            for i in range(divisions+1):
                t = i / divisions
                point_on_curve = rs.EvaluateCurve(curve_id, t)
                if point_on_curve:
                    curve_points.append(point_on_curve)
            # 创建直线连接这些点
            if len(curve_points) >= 2:
                polyline = rs.AddPolyline(curve_points)
                if polyline:
                    print("折线创建成功")
            rs.DeleteObject(curve_id)  # 可选：删除原曲线
        else:
