def safe_add_nurbs_curve(points, knots, degree, weights=None):
    if not points or len(points) == 0:
        print("错误：控制点列表为空")
        return None
    if not knots or len(knots) == 0:
        print("错误：节点向量为空")
        return None
    if degree < 1:
        print("错误：阶数必须大于等于1")
        return None
    expected_knots = len(points) + degree - 1
    if len(knots) != expected_knots:
        print(f"错误：节点向量长度应为 {expected_knots}，实际为 {len(knots)}")
        return None
    if weights is not None:
        if len(weights) != len(points):
            print(f"错误：权重列表长度应为 {len(points)}，实际为 {len(weights)}")
            return None
        for w in weights:
            if w <= 0:
                print("错误：权重必须大于0")
                return None
    try:
        curve_id = rs.AddNurbsCurve(points, knots, degree, weights)
        return curve_id
    except Exception as e:
        print(f"添加曲线时出错：{e}")
        return None

