def safe_close_curve(curve_id, tolerance=-1.0):
    """安全闭合曲线，返回新曲线ID或None"""
    if not curve_id:
        return None
    # 检查对象是否存在
    if not rs.IsObject(curve_id):
        return None
    # 检查是否曲线
    if rs.ObjectType(curve_id) != rs.filter.curve:
        return None
    # 如果已闭合，直接返回
    if rs.IsCurveClosed(curve_id):
        return curve_id
    # 检查是否可闭合
    if not rs.IsCurveClosable(curve_id):
        return None
    try:
        new_curve = rs.CloseCurve(curve_id, tolerance)
        return new_curve
    except Exception as e:
        raise RuntimeError("闭合曲线失败：" + str(e))

