# 获取所有曲线对象
curve_ids = rs.GetObjects("选择平面曲线", rs.filter.curve)
if not curve_ids:
    print("未选择任何对象")
else:
    for curve_id in curve_ids:
        # 检查是否为平面曲线
        if rs.IsCurve(curve_id) and rs.IsCurvePlanar(curve_id):
            # 获取法线
            normal = rs.CurveNormal(curve_id)
            if normal:
                # 获取曲线中心点
                domain = rs.CurveDomain(curve_id)
                mid_param = (domain[0] + domain[1]) / 2.0
                mid_point = rs.EvaluateCurve(curve_id, mid_param)
                # 在中心点创建箭头指示法线方向
                arrow_end = rs.PointAdd(mid_point, normal)
                rs.AddArrowhead(mid_point, arrow_end)  # 假设有AddArrowhead函数，实际可用AddLine和AddCone等组合
            else:
                print("曲线法线获取失败")
        else:
            print("跳过非平面曲线")

