def safe_normalize_parameter(curve_id, parameter):
    """安全转换曲线参数为归一化参数"""
    if curve_id is None or parameter is None:
        return None
    if not rs.IsCurve(curve_id):
        return None
    try:
        normalized = rs.CurveNormalizedParameter(curve_id, parameter)
        return normalized
    except Exception:
        return None

