def safe_evaluate_curve(curve_id, t):
    if not rs.IsCurve(curve_id):
        return None
    domain = rs.CurveDomain(curve_id)
    if t < domain[0] or t > domain[1]:
        return None
    try:
        point = rs.EvaluateCurve(curve_id, t)
        return point
    except:
