import rhinoscriptsyntax as rs

def fit_or_connect(points):
    if not points or len(points) < 2:
        return None
    # 检查是否共线：取前两点构建向量，检查其余点是否在线上
    pt0, pt1 = points[0], points[1]
    for pt in points[2:]:
        # 计算点到直线的距离，如果大于容差则认为不共线
        dist = rs.DistanceToLine(pt, pt0, pt1)
        if dist > 0.001:
            # 不共线，使用拟合
            line = rs.LineFitFromPoints(points)
            if line:
                return rs.AddLine(line.From, line.To)
            else:
                return None
    # 所有点共线，直接连接首尾
    return rs.AddLine(points[0], points[-1])

points = rs.GetPoints("选择点", press_enter=True)
if points and len(points) > 1:
    curve = fit_or_connect(points)
    if curve:
