                elif result == 2:
                    # curve1 在 curve2 内，在 curve1 中心加点
                    center = rs.CurveAreaCentroid(curve1)[0]
                    rs.AddPoint(center)
                elif result == 3:
                    center = rs.CurveAreaCentroid(curve2)[0]
                    rs.AddPoint(center)
            else:
                print("曲线不共面")
        else:
            print("曲线未闭合")
    else:
        print("曲线不平面")

import rhinoscriptsyntax as rs

def safe_containment(curve_a, curve_b, plane=None, tolerance=None):
    """安全地判断两条闭合平面曲线的包含关系，处理None参数"""
    if curve_a is None or curve_b is None:
        print("曲线标识为None")
        return None
    if not rs.IsObject(curve_a) or not rs.IsObject(curve_b):
        print("曲线无效或已删除")
        return None
    if not rs.IsCurve(curve_a) or not rs.IsCurve(curve_b):
        print("对象不是曲线")
        return None
    if not rs.IsCurvePlanar(curve_a) or not rs.IsCurvePlanar(curve_b):
        print("曲线不平面")
        return None
    if not rs.IsCurveClosed(curve_a) or not rs.IsCurveClosed(curve_b):
        print("曲线未闭合")
        return None
    # 检查共面性（可选）
    if not rs.IsCurveInPlane(curve_a) or not rs.IsCurveInPlane(curve_b):
        print("曲线不共面")
        return None
    try:
        result = rs.PlanarClosedCurveContainment(curve_a, curve_b, plane, tolerance)
        return result
    except Exception as e:
        print(f"函数执行出错: {e}")
        return None

