        if rs.IsCurveClosed(curve1) and rs.IsCurveClosed(curve2):
            if rs.IsCurveInPlane(curve1) and rs.IsCurveInPlane(curve2):
                result = rs.PlanarClosedCurveContainment(curve1, curve2)
                if result == 2:
                    # curve1 在 curve2 内，在 curve2 内部随机取点
                    bbox = rs.BoundingBox(curve2)
                    min_pt = bbox[0]
                    max_pt = bbox[2]
                    for _ in range(100):
                        x = random.uniform(min_pt.X, max_pt.X)
                        y = random.uniform(min_pt.Y, max_pt.Y)
                        z = min_pt.Z  # 平面曲线，保持Z一致
                        point = (x, y, z)
                        if rs.PointInPlanarClosedCurve(point, curve2, plane=rs.ViewCPlane()) == 1:
                            rs.AddPoint(point)
                            print("在内部生成点")
                            break
                    else:
                        print("未找到内部点")
                elif result == 3:
                    # curve2 在 curve1 内，在 curve1 内部随机取点
                    bbox = rs.BoundingBox(curve1)
                    min_pt = bbox[0]
                    max_pt = bbox[2]
