import rhinoscriptsyntax as rs

def safe_planar_collision(curve_a, curve_b, plane=None, tolerance=None):
    if not curve_a or not curve_b:
        return False
    if not rs.IsCurve(curve_a) or not rs.IsCurve(curve_b):
        return False
    if not rs.IsCurvePlanar(curve_a) or not rs.IsCurvePlanar(curve_b):
        return False
    if plane is None:
        # 使用当前构造平面
        pass  # rs.PlanarCurveCollision 默认会处理
    try:
        return rs.PlanarCurveCollision(curve_a, curve_b, plane, tolerance)
    except:
        return False

