def remove_internal_knots(curve_id):
    """删除曲线内部节点（只保留首尾节点）"""
    # 获取曲线所有节点参数
    knots = rs.CurveKnots(curve_id)
    if not knots or len(knots) <= 2:
        print("曲线只有两端节点，无需删除")
        return True
    # 从后往前删除中间节点，避免参数变化
    for i in range(len(knots)-2, 0, -1):
        success = rs.RemoveCurveKnot(curve_id, knots[i])
        if not success:
            print(f"删除节点 {knots[i]} 失败")
            return False
    return True

