def safe_select_grip(object_id, index):
    """安全选中控制点，返回成功与否"""
    if not rs.IsObject(object_id):
        print("对象不存在")
        return False
    if not rs.EnableObjectGrips(object_id):
        print("无法启用控制点")
        return False
    count = rs.ObjectGripCount(object_id)
    if index < 0 or index >= count:
        print(f"索引{index}无效，有效范围0-{count-1}")
        return False
    return rs.SelectObjectGrip(object_id, index)

