def create_unique_group(base_name):
    """创建一个唯一名称的组，如果名称已存在则添加数字后缀"""
    if not rs.IsGroup(base_name):
        return rs.AddGroup(base_name)
    else:
        # 名称已存在，尝试添加数字后缀
        for i in range(1, 100):
            new_name = "{}_{}".format(base_name, i)
            if not rs.IsGroup(new_name):
                return rs.AddGroup(new_name)
        # 如果所有数字都被占用，返回 None
        return None

