def unlock_all_locked_groups():
    # 获取所有组名
    groups = rs.GroupNames()
    if not groups:
        print("没有找到任何组")
        return

    total_unlocked = 0
    for group_name in groups:
        # 检查组是否锁定（假设锁定组无法直接检测，尝试解锁即可）
        result = rs.UnlockGroup(group_name)
        if result is not None:
            total_unlocked += result

    if total_unlocked > 0:
        print("成功解锁了 {} 个对象".format(total_unlocked))
    else:
        print("没有锁定的组需要解锁")

