def check_if_directional(light_guid):
    """判断给定GUID的灯光是否为平行光。

    Args:
        light_guid: 灯光对象的GUID

    Returns:
        bool: 如果是平行光则返回True，否则返回False（包括无效参数）
    """
    if not light_guid:
        return False
    try:
        # 检查对象是否存在且为灯光
        if rs.IsObject(light_guid) and rs.ObjectType(light_guid) == rs.filter.light:
            return rs.IsDirectionalLight(light_guid)
        else:
            return False
    except:
        return False

