import rhinoscriptsyntax as rs

def safe_is_light_reference(object_id):
    """Safely check if a light is a reference. Returns False for invalid input."""
    if object_id is None:
        return False
    if not rs.IsObject(object_id):
        return False
    # 进一步确认是否是灯光对象（可选）
    if rs.ObjectType(object_id) != rs.filter.light:
        return False
    try:
        return rs.IsLightReference(object_id)
    except:
        return False

