import rhinoscriptsyntax as rs

# 选择曲线
curve_id = rs.GetObject("选择一条曲线", rs.filter.curve)
if not curve_id:
    print("未选择曲线")
else:
    # 拾取测试点
    point = rs.GetPoint("拾取一个点")
    if point:
        # 获取曲线起点
        start_pt = rs.CurveStartPoint(curve_id)
        if start_pt:
            # 构造从起点到点方向的无限线（简化：使用起点和切线方向）
            # 但要求是曲线起点，所以直接用起点和另一点构造线
            # 这里假设线为从起点沿切线方向无限延伸，但更简单：用起点和测试点方向构造线
            # 注意：LineClosestPoint用于无限线，所以我们取起点和沿切线方向一点
            tangent = rs.CurveTangent(curve_id, rs.CurveParameter(curve_id, 0))
            if tangent:
                far_point = (start_pt[0] + tangent[0]*1000, start_pt[1] + tangent[1]*1000, start_pt[2] + tangent[2]*1000)
                line = (start_pt, far_point)
                closest = rs.LineClosestPoint(line, point)
                if closest:
                    rs.AddPoint(closest)
                    print("最近点已添加")
                else:
                    print("计算失败")
            else:
                print("无法获取切线")
        else:
            print("无法获取曲线起点")

