import rhinoscriptsyntax as rs

def safe_line_intersection(lineA, lineB):
    if lineA is None or lineB is None:
        print("输入直线为None")
        return None
    if not rs.IsLine(lineA) or not rs.IsLine(lineB):
        print("输入不是有效的直线对象")
        return None
    try:
        result = rs.LineLineIntersection(lineA, lineB)
        return result
    except Exception as e:
        print("计算交点时出错:", e)
        return None

# 使用示例
lineA = None
lineB = rs.AddLine((0,0,0), (10,10,0))
result = safe_line_intersection(lineA, lineB)
if result:
    print("交点:", result)
else:
    print("未成功计算")

