def safe_curve_mesh_intersection(curve_id, mesh_id, return_faces=False):
    """安全计算曲线与网格的交点，处理无效参数"""
    if not curve_id or not mesh_id:
        return None
    # 检查对象是否仍然存在
    if not rs.IsObject(curve_id) or not rs.IsObject(mesh_id):
        return None
    # 检查类型
    if rs.ObjectType(curve_id) != rs.filter.curve or rs.ObjectType(mesh_id) != rs.filter.mesh:
        return None
    try:
        result = rs.CurveMeshIntersection(curve_id, mesh_id, return_faces)
        return result
    except Exception as e:
        print("计算错误: {}".format(e))
        return None

