def quad_percentage(mesh_id):
    """Returns the percentage of quad faces in a mesh. Returns 0 if invalid."""
    if not mesh_id or not rs.IsObject(mesh_id) or rs.ObjectType(mesh_id) != rs.filter.mesh:
        return 0.0
    total = rs.MeshFaceCount(mesh_id)
    if total == 0:
        return 0.0
    quad = rs.MeshQuadCount(mesh_id)
    return float(quad) / total * 100.0

