def safe_split_disjoint_mesh(mesh_guid, delete_input=False):
    """安全拆分不相连网格，处理边界情况"""
    if mesh_guid is None:
        print("错误：未提供物体")
        return []
    if not rs.IsMesh(mesh_guid):
        print("错误：物体不是网格")
        return []
    if rs.DisjointMeshCount(mesh_guid) <= 1:
        print("网格已经是连通的，无需拆分")
        return [mesh_guid]
    try:
        result = rs.SplitDisjointMesh(mesh_guid, delete_input)
        return result if result else []
    except Exception as e:
        print("拆分失败:", str(e))
        return []

