    if not obj_id:
        return None
    angle = abs(angle)
    if copy:
        # 先复制
        new_id = rs.CopyObject(obj_id)
        if not new_id:
            return None
        return rs.ShearObject(new_id, origin, refpt, angle, copy=False)
    else:
        return rs.ShearObject(obj_id, origin, refpt, angle, copy=False)

