def safe_show_objects(object_ids):
    """安全显示物体，忽略无效ID。"""
    if not object_ids:
        return 0
    valid_ids = []
    for obj in object_ids:
        if obj is None:
            continue
        try:
            if rs.IsObject(obj):
                valid_ids.append(obj)
        except:
            pass
    if valid_ids:
        return rs.ShowObjects(valid_ids)
    return 0

