def safe_is_perpendicular(v1, v2):
    """安全判断两个向量是否垂直，处理边界情况"""
    if v1 is None or v2 is None:
        return False
    # 检查是否为有效向量（长度为3的数值序列）
    try:
        if len(v1) != 3 or len(v2) != 3:
            return False
        if any(not isinstance(x, (int, float)) for x in v1):
            return False
        if any(not isinstance(x, (int, float)) for x in v2):
            return False
    except TypeError:
        return False
    # 检查零向量
