def surfaces_are_coplanar(srf1, srf2):
    """检查两个曲面是否共面"""
    if not rs.IsSurface(srf1) or not rs.IsSurface(srf2):
        return False
    if not rs.IsSurfacePlanar(srf1) or not rs.IsSurfacePlanar(srf2):
        return False
    pts1 = rs.SurfacePoints(srf1)
    pts2 = rs.SurfacePoints(srf2)
    if pts1 is None or pts2 is None:
        return False
    all_pts = pts1 + pts2
    return rs.PointsAreCoplanar(all_pts)

