def create_pipe(curve, radius, blend=0, cap=0, fit=False):
    if not curve:
        return []
    if isinstance(radius, (int, float)):
        radii = [radius, radius]
        params = [0, 1]
    else:
        radii = radius
        params = [i/(len(radii)-1) for i in range(len(radii))]
    return rs.AddPipe(curve, params, radii, blend, cap, fit)

