import rhinoscriptsyntax as rs

def safe_boolean_intersection(surfaces1, surfaces2, delete=True):
    """安全的布尔交集，处理空输入"""
    if not surfaces1 or not surfaces2:
        return []
    # 确保输入为列表
    if not isinstance(surfaces1, (list, tuple)):
        surfaces1 = [surfaces1]
    if not isinstance(surfaces2, (list, tuple)):
        surfaces2 = [surfaces2]
    try:
        result = rs.BooleanIntersection(surfaces1, surfaces2, delete_input=delete)
        if result is None:
            return []
        return result
    except Exception as e:
        print("错误：", e)
        return []

