# 选择第一组
set1 = rs.GetObjects("选择第一组曲面", rs.filter.surface | rs.filter.polysurface)
if not set1:
    print("未选择第一组")
else:
    # 选择第二组
    set2 = rs.GetObjects("选择第二组曲面", rs.filter.surface | rs.filter.polysurface)
    if not set2:
        print("未选择第二组")
    else:
        # 执行布尔交集，删除原始对象
        result = rs.BooleanIntersection(set1, set2, delete_input=True)
        if not result:
            print("布尔交集结果为空，没有重叠区域")
        else:
            # 将结果合并为一个多重曲面
            joined = rs.JoinSurfaces(result, delete_input=True)
            if joined:
                # 设置颜色为红色
                rs.ObjectColor(joined, [255, 0, 0])
                rs.Redraw()
                print("成功创建红色多重曲面，ID：", joined)
            else:
                print("合并失败")

