import rhinoscriptsyntax as rs

def safe_cap_planar_holes(surface_id):
    """安全封闭平面孔洞，处理无效输入。"""
    if not surface_id:
        print("输入ID为空。")
        return False
    if not rs.IsObject(surface_id):
        print("对象不存在。")
        return False
    if not (rs.IsSurface(surface_id) or rs.IsPolysurface(surface_id)):
        print("对象不是曲面或多重曲面。")
        return False
    try:
        result = rs.CapPlanarHoles(surface_id)
        return result
    except Exception as e:
        print("封闭时出错：", str(e))
        return False

# 使用示例
