import rhinoscriptsyntax as rs

# 选择曲面
obj = rs.GetObject("选择曲面", rs.filter.surface)
if obj:
    # 提取边缘曲线
    edges = rs.DuplicateEdgeCurves(obj)
    if edges:
        # 合并所有边缘曲线为一条复合曲线
        joined = rs.JoinCurves(edges, delete_input=True)
        if joined:
            # 创建图层（如果不存在）
            layer = "Edges"
            if not rs.IsLayer(layer):
                rs.AddLayer(layer)
            # 将合并后的曲线移到该图层
            for crv in joined:
                rs.ObjectLayer(crv, layer)
            print("边缘曲线已合并并放入图层 'Edges'")
        else:
            print("曲线合并失败")
    else:
        print("提取边缘曲线失败")
