import rhinoscriptsyntax as rs

def safe_evaluate_surface(surface_id, u, v):
    """
    安全评估曲面，处理无效输入。
    """
    if surface_id is None:
        return None
    if not rs.IsSurface(surface_id):
        return None
    try:
        point = rs.EvaluateSurface(surface_id, u, v)
        return point
    except Exception:
        return None

