            end_on_surf = rs.EvaluateSurface(surface, proj_end[0], proj_end[1])
            if start_on_surf and end_on_surf:
                curve = rs.ShortPath(surface, start_on_surf, end_on_surf)
                if curve:
                    print("最短路径已创建")
                else:
                    print("创建最短路径失败")
