def extract_torus_params(surface_id):
    """
    提取圆环曲面的平面、主半径和次半径。
    参数:
        surface_id: 曲面对象的GUID
    返回:
        包含(plane, major_radius, minor_radius)的元组，失败返回None
    """
    torus_info = rs.SurfaceTorus(surface_id)
    if torus_info:
        plane, major, minor = torus_info
        # 确保平面为WorldXY（示例中检查，实际可按需调整）
        if rs.IsPlaneWorldXY(plane):
            return (plane, major, minor)
        else:
            print("平面不是WorldXY，但返回原始平面")
            return (plane, major, minor)
    else:
        return None

