import rhinoscriptsyntax as rs

def safe_get_torus_params(surface_id):
    """
    安全获取圆环曲面参数，失败时返回默认值。
    参数:
        surface_id: 曲面对象的GUID，可能为None
    返回:
        (plane, major_radius, minor_radius) 三元组
    """
    if surface_id is None:
        print("输入为None，使用默认值")
        return (rs.WorldXYPlane(), 5.0, 2.0)

    if not rs.IsObject(surface_id):
        print("无效对象ID，使用默认值")
        return (rs.WorldXYPlane(), 5.0, 2.0)

    if not rs.IsTorus(surface_id):
        print("对象不是圆环曲面，使用默认值")
        return (rs.WorldXYPlane(), 5.0, 2.0)

    torus_info = rs.SurfaceTorus(surface_id)
    if torus_info is None:
        print("获取圆环参数失败，使用默认值")
        return (rs.WorldXYPlane(), 5.0, 2.0)

    return torus_info

