    report = []
    for surf in surfaces:
        if rs.IsTorus(surf):
            torus_info = rs.SurfaceTorus(surf)
            if torus_info:
                plane, major, minor = torus_info
                report.append({
                    "id": surf,
                    "major_radius": major,
