def get_or_set_default(section, entry, default_value):
    value = rs.GetDocumentData(section, entry)
    if value is None:
        # 如果不存在，设置默认值
        rs.SetDocumentData(section, entry, str(default_value))
        return str(default_value)
    else:
        return value

