import rhinoscriptsyntax as rs

def get_angle_with_retry(base, ref=None, default=0, max_attempts=3):
    """
    获取角度，如果用户取消则重试最多max_attempts次。
    """
    for attempt in range(max_attempts):
        angle = rs.GetAngle(base, ref, default)
        if angle is not None:
            return angle
        if attempt < max_attempts - 1:
            print("未输入角度，请重试（剩余{}次）".format(max_attempts - attempt - 1))
    print("已取消角度输入")
    return None

# 示例
base = rs.GetPoint("指定基点")
if base:
    ref = rs.GetPoint("指定参考点", base)
    if ref:
        angle = get_angle_with_retry(base, ref, default=45)
        if angle is not None:
            print("最终角度：", angle)

