import rhinoscriptsyntax as rs

def safe_get_mesh_faces(mesh_id, prompt="选择面", min_count=1, max_count=0):
    """安全地获取网格面索引，处理错误和取消情况"""
    if not mesh_id:
        print("无效的网格ID")
        return None
    try:
        indices = rs.GetMeshFaces(mesh_id, prompt, min_count, max_count)
        if indices is None:
            print("用户取消了选择或发生错误")
            return None
        # 验证返回的是列表且元素为整数
        if not isinstance(indices, list) or not all(isinstance(i, int) for i in indices):
            print("返回的数据格式异常")
            return None
        return indices
    except Exception as e:
        print("发生异常:", e)
        return None

