def safe_angle(point1, point2, plane=True):
    """安全计算两点角度，处理None和点对象"""
    if point1 is None or point2 is None:
        return None
    # 如果是点对象，转换为坐标
    if isinstance(point1, str):
        point1 = rs.PointCoordinates(point1)
    if isinstance(point2, str):
        point2 = rs.PointCoordinates(point2)
    if point1 is None or point2 is None:
        return None
    try:
        result = rs.Angle(point1, point2, plane)
        return result
    except:
        return None

