def safe_create_point(point, y=None, z=None):
    """安全创建点，输入无效时返回None"""
    try:
        if point is None:
            return None
        if y is not None:
            # 检查坐标能否转换为数字
            try:
                x_val = float(point)
                y_val = float(y)
                z_val = float(z) if z is not None else 0.0
                return rs.CreatePoint(x_val, y_val, z_val)
            except (ValueError, TypeError):
                return None
        else:
            # 尝试转换point为点
            if isinstance(point, Rhino.Geometry.Point3d):
                return rs.CreatePoint(point)
            elif isinstance(point, (list, tuple)) and len(point) >= 2:
                try:
                    return rs.CreatePoint(float(point[0]), float(point[1]), float(point[2]) if len(point)>2 else 0.0)
                except:
                    return None
            else:
                return None
    except Exception:
        return None

