def parse_vector_from_string(s):
    # 按逗号分割字符串并转换为浮点数
    parts = s.split(',')
    if len(parts) == 2:
        x, y = map(float, parts)
        return rs.CreateVector(x, y)  # z默认为0
    elif len(parts) == 3:
        x, y, z = map(float, parts)
        return rs.CreateVector(x, y, z)
    else:
        raise ValueError("字符串格式错误，应为 'x,y' 或 'x,y,z'")

