def safe_add_detail(layout_id, corner1, corner2, title=None, projection=1):
    if not layout_id:
        print("Error: layout_id is None or invalid")
        return None
    if corner1 is None or corner2 is None:
        print("Error: corner points cannot be None")
        return None
    if projection < 1 or projection > 7:
        print("Error: projection must be between 1 and 7")
        return None
    try:
        detail_id = rs.AddDetail(layout_id, corner1, corner2, title, projection)
        if detail_id:
            rs.Redraw()
        return detail_id
    except Exception as e:
        print("Error occurred:", e)
        return None

