import rhinoscriptsyntax as rs

def safe_toggle_maximize(view=None):
    """安全切换视图最大化状态。如果view为None，则使用当前视图。如果视图不存在或无效，则忽略。"""
    try:
        if view is None:
            view = rs.CurrentView()
        if view and rs.IsView(view):
            rs.MaximizeRestoreView(view)
        else:
            print("无效的视图名称或标识符")
    except Exception as e:
        print(f"操作失败: {e}")

