def safe_rotate_camera(view=None, direction=0, angle=10):
    """安全地旋转相机，如果view为None则使用当前视图。"""
    try:
        if view is None:
            # 获取当前活动视图
            view = rs.CurrentView()
            if not view:
                return False
        # 执行旋转
        result = rs.RotateCamera(view=view, direction=direction, angle=angle)
        return result
    except Exception:
        return False

