def set_grid_visibility(view_name=None, show=None):
    if view_name:
        view = rs.ViewByName(view_name)
        if not view:
            print("View not found, using current view.")
            view = rs.CurrentView()
    else:
        view = rs.CurrentView()
    if show is None:
        return rs.ShowGrid(view)
    else:
        return rs.ShowGrid(view, show=show)

