def toggle_world_axes(view=None, show=None):
    if view is None:
        view = rs.CurrentView()
    current = rs.ShowWorldAxes(view)
    if show is None:
        show = not current
    if current != show:
        rs.ShowWorldAxes(view, show)
    return current

