import rhinoscriptsyntax as rs

def safe_zoom_selected(view=None):
    """安全地缩放视图到选中物体"""
    if rs.SelectedObjects():
        try:
            if view:
                rs.ZoomSelected(view)
            else:
                rs.ZoomSelected()
        except Exception as e:
            rs.MessageBox("缩放失败：" + str(e))
    else:
        rs.MessageBox("没有选中任何物体")

